# Let's build a matching function and find all songs that match the old_songs entries
def song_matches_old(song, old_entry):
    # Compare title (case-insensitive)
    if song['title'].lower() != old_entry['title'].lower():
        return False
    # Compare artist names (case-insensitive, set comparison)
    song_artists = {a['name'].lower() for a in song['artists']}
    old_artists = {a.lower() for a in old_entry['artists']}
    return song_artists == old_artists

# Find matching song IDs
matching_song_ids = []
for sid, song in song_details.items():
    for old in old_songs:
        if song_matches_old(song, old):
            matching_song_ids.append(sid)
            print(f"Match: song_id={sid}, title={song['title']}, artists={[a['name'] for a in song['artists']]}")
            break

print("Total matches:", len(matching_song_ids))

